//! Predeployed contract addresses and bytecode for the Neunode genesis block.
//!
//! Contracts are deployed at deterministic addresses in the `0x0000...00XX` range.
//! Bytecode and storage are generated by `scripts/genesis_codegen.py` which deploys
//! all contracts on Anvil, extracts the deployed state, and remaps addresses to
//! the deterministic predeploy addresses.
//!
//! To regenerate: `python3 scripts/genesis_codegen.py`

use alloy::primitives::{address, Address, Bytes, B256};
use std::collections::BTreeMap;

/// JSON file generated by the codegen script, embedded at compile time.
const GENESIS_PREDEPLOYS_JSON: &str = include_str!("genesis_predeploys.json");

/// Descriptor for a contract predeployed at genesis.
#[derive(Debug, Clone)]
pub struct PredeployedContract {
    /// Human-readable name for logging and tooling.
    pub name: String,
    /// Deterministic address where the contract is deployed.
    pub address: Address,
    /// Deployed bytecode (runtime code, not init code).
    pub bytecode: Bytes,
    /// Pre-initialized storage slots (slot -> value).
    pub storage: BTreeMap<B256, B256>,
}

// Deterministic predeploy addresses.

/// Diamond proxy (EIP-2535) - entry point for all facets.
pub const DIAMOND_PROXY: Address = address!("0000000000000000000000000000000000001001");

/// NeunodeIdentity - DID registry for AI agents.
pub const NEUNODE_IDENTITY: Address = address!("0000000000000000000000000000000000001002");

/// NeunodeBounty - bounty state machine.
pub const NEUNODE_BOUNTY: Address = address!("0000000000000000000000000000000000001003");

/// NeunodeEscrow - bilateral escrow for bounty payments.
pub const NEUNODE_ESCROW: Address = address!("0000000000000000000000000000000000001004");

/// NeunodeRegistry - agent capability and endpoint registry.
pub const NEUNODE_REGISTRY: Address = address!("0000000000000000000000000000000000001005");

/// nCompute token - GPU/CPU hours resource token.
pub const COMPUTE_TOKEN: Address = address!("0000000000000000000000000000000000001006");

/// nTrain token - training compute resource token.
pub const TRAIN_TOKEN: Address = address!("0000000000000000000000000000000000001007");

/// nBandwidth token - bandwidth resource token.
pub const BANDWIDTH_TOKEN: Address = address!("0000000000000000000000000000000000001008");

/// nStorage token - storage resource token.
pub const STORAGE_TOKEN: Address = address!("0000000000000000000000000000000000001009");

/// ModelRegistry - model lineage DAG with content-addressed models.
pub const MODEL_REGISTRY: Address = address!("000000000000000000000000000000000000100a");

/// RoyaltySplitter - ERC-2981 royalty distribution with BFS lineage traversal.
pub const ROYALTY_SPLITTER: Address = address!("000000000000000000000000000000000000100b");

