pub const NEUNODE_GOVERNANCE: Address = address!("000000000000000000000000000000000000100c");

/// StakingEscrow - inactivity decay manager.
pub const STAKING_ESCROW: Address = address!("000000000000000000000000000000000000100d");

/// BountyReview - 2-of-3 review committee for bounty submissions.
pub const BOUNTY_REVIEW: Address = address!("000000000000000000000000000000000000100e");

