pub const DIAMOND_LOUPE_FACET: Address = address!("0000000000000000000000000000000000001011");

/// EIP-4788 beacon roots contract (system predeploy for Cancun).
pub const BEACON_ROOTS: Address = address!("000F3df6D732807Ef1319fB7B8bB8522d0Beac02");

/// Returns all Neunode-specific predeployed contracts with real bytecode and storage.
///
/// Bytecode and storage are loaded from `genesis_predeploys.json`, which is generated
/// by deploying contracts on Anvil and extracting the resulting state. The state is
/// remapped so cross-contract references point to the deterministic predeploy addresses.
pub fn neunode_predeploys() -> Vec<PredeployedContract> {
    let json: serde_json::Value = serde_json::from_str(GENESIS_PREDEPLOYS_JSON)
        .expect("genesis_predeploys.json must be valid JSON");

    let predeploys = json
        .get("predeploys")
        .and_then(|v| v.as_array())
        .expect("genesis_predeploys.json must have a 'predeploys' array");

    predeploys
        .iter()
        .map(|entry| {
            let name = entry["name"].as_str().unwrap_or("unknown").to_string();
            let address: Address =
                entry["address"].as_str().and_then(|s| s.parse().ok()).unwrap_or(Address::ZERO);
            let bytecode: Bytes = entry["bytecode"]
                .as_str()
                .and_then(|s| if s == "0x" || s.is_empty() { None } else { s.parse().ok() })
                .unwrap_or_default();

            let storage = entry["storage"]
                .as_object()
                .map(|obj| {
                    obj.iter()
                        .filter_map(|(slot, value)| {
                            let slot: B256 = slot.parse().ok()?;
                            let val: B256 = value.as_str()?.parse().ok()?;
                            Some((slot, val))
                        })
                        .collect()
                })
                .unwrap_or_default();

            PredeployedContract { name, address, bytecode, storage }
        })
        .collect()
}

/// Returns all predeploy addresses as a vector, useful for quick lookups.
pub fn predeploy_addresses() -> Vec<Address> {
    neunode_predeploys().iter().map(|c| c.address).collect()
}
